arguments.command:
cd /app && python3 -c "
import json,re
d=json.load(open('/tmp/fpbase.json'))
fp={p['name']:p['seq'] for p in d}
# pdb fastas
pdb={}
cur=None
for line in open('/tmp/pdb_fastas.txt'):
    line=line.strip()
    if line.startswith('====='):
        cur=line.strip('=')
        pdb[cur]=''
    elif line.startswith('>'):
        pdb.setdefault(cur, '')
        # multiple chains -> keep first only handled below
        if pdb[cur]=='' : pdb[cur]='|'
    elif line:
        if pdb[cur].endswith('|') or not pdb[cur]:
            pass
        pdb[cur]+=line
# simpler: reparse capturing first chain seq
pdb={}
cur=None; grab=False
for line in open('/tmp/pdb_fastas.txt'):
    s=line.strip()
    if s.startswith('====='):
        cur=s.strip('='); pdb[cur]=''; grab=False; n=0
    elif s.startswith('>'):
        n=n+1 if 'n' in dir() else 1
    elif s:
        pdb[cur]+=s
def show(name,pid):
    print('===',name,pid)
    print('fpbase:',fp[name])
    print('pdb   :',pdb[pid])
show('Clover','5WJ2')
show('mCherry','2H5Q')
print('=== SNAP 3KZY'); print('pdb:',pdb['3KZY'])
"

